using System.Text.Json;

namespace DynaSharp.UnitTests.Operations;

/// <summary>
/// The vectors of <c>operation_vectors.json</c>, generated by <c>generate_operation_vectors.py</c> with botocore's serializer and
/// parser, so that the wire format is pinned to the reference implementation and not to this library.
/// </summary>
internal static class OperationVectors
{
    /// <summary>The ARN form of a table name, as used by the table-name vectors.</summary>
    public const string TableArn = "arn:aws:dynamodb:eu-central-1:123456789012:table/Users";

    /// <summary>
    /// Text full of characters that need escaping in JSON. Built from code points, because tools like to normalize escapes in
    /// source text; the same text is built in <c>generate_operation_vectors.py</c>.
    /// </summary>
    public static readonly string SpecialText =
        "quote \" backslash \\ slash / tab \t newline \n control " + (char)1 + " " + (char)0xE9 + " " + char.ConvertFromUtf32(0x1F600) + " </script>";

    /// <summary>An attribute name with a non-ASCII character, built like <see cref="SpecialText"/>.</summary>
    public static readonly string NaiveName = "na" + (char)0xEF + "ve";

    private static readonly Lazy<(IReadOnlyList<RequestVector> Requests, IReadOnlyList<RequestVector> Commands, IReadOnlyList<ResponseVector> Responses, IReadOnlyList<ErrorVector> Errors)> Data = new(Load);

    public static IReadOnlyList<RequestVector> Requests => Data.Value.Requests;

    public static IReadOnlyList<RequestVector> Commands => Data.Value.Commands;

    public static IReadOnlyList<ResponseVector> Responses => Data.Value.Responses;

    public static IReadOnlyList<ErrorVector> Errors => Data.Value.Errors;

    public static IEnumerable<string> ErrorNames() => Errors.Select(vector => vector.Name);

    public static ErrorVector Error(string name) => Errors.Single(vector => vector.Name == name);

    /// <summary>The counterpart of <c>ALL_VALUE_TYPES</c> in the generator: an attribute of every DynamoDB type, by placeholder name.</summary>
    /// <returns>A new dictionary.</returns>
    public static Dictionary<string, AttributeValue> AllValueTypes() => new()
    {
        [":s"] = "text",
        [":n"] = AttributeValue.FromNumber("-12.5E+3"),
        [":b"] = AttributeValue.FromBinary([0, 1, 2, 253, 254, 255]),
        [":t"] = AttributeValue.FromBool(true),
        [":f"] = AttributeValue.FromBool(false),
        [":null"] = AttributeValue.Null,
        [":ss"] = AttributeValue.FromStringSet(["a", "b"]),
        [":ns"] = AttributeValue.FromNumberSet(["1", "2.5"]),
        [":bs"] = AttributeValue.FromBinarySet([[0, 1], [255]]),
        [":l"] = AttributeValue.FromList(["x", AttributeValue.FromNumber("1"), AttributeValue.FromList([]), AttributeValue.FromMap([]), AttributeValue.FromBool(false)]),
        [":m"] = AttributeValue.FromMap(
        [
            KeyValuePair.Create("inner", AttributeValue.FromMap([KeyValuePair.Create("deep", AttributeValue.FromList([AttributeValue.FromNumber("1"), "two"]))])),
            KeyValuePair.Create("empty", (AttributeValue)string.Empty),
        ]),
    };

    /// <summary>The counterpart of <c>numbered_key</c> in the generator.</summary>
    /// <param name="index">The number.</param>
    /// <returns>A key with a string partition key and a number sort key.</returns>
    public static Dictionary<string, AttributeValue> NumberedKey(int index) => new()
    {
        ["pk"] = "USER#" + index.ToString(System.Globalization.CultureInfo.InvariantCulture),
        ["sk"] = AttributeValue.FromNumber(index),
    };

    public static IEnumerable<string> RequestNames(string operation) =>
        Requests.Where(vector => vector.Operation == operation).Select(vector => vector.Name);

    public static IEnumerable<string> ResponseNames(string operation) =>
        Responses.Where(vector => vector.Operation == operation).Select(vector => vector.Name);

    public static RequestVector Request(string operation, string name) =>
        Requests.Single(vector => vector.Operation == operation && vector.Name == name);

    public static ResponseVector Response(string operation, string name) =>
        Responses.Single(vector => vector.Operation == operation && vector.Name == name);

    private static (IReadOnlyList<RequestVector> Requests, IReadOnlyList<RequestVector> Commands, IReadOnlyList<ResponseVector> Responses, IReadOnlyList<ErrorVector> Errors) Load()
    {
        using var stream = typeof(OperationVectors).Assembly.GetManifestResourceStream("operation_vectors.json")
            ?? throw new InvalidOperationException("The embedded resource operation_vectors.json is missing.");
        using var document = JsonDocument.Parse(stream);
        var root = document.RootElement;
        var requests = ReadRequests(root.GetProperty("requests"));
        var commands = ReadRequests(root.GetProperty("commandRequests"));
        var responses = root.GetProperty("responses").EnumerateArray()
            .Select(element => new ResponseVector(
                element.GetProperty("operation").GetString()!,
                element.GetProperty("name").GetString()!,
                element.GetProperty("wire").GetString()!,
                element.GetProperty("parsed").GetRawText()))
            .ToList();
        var errors = root.GetProperty("errors").EnumerateArray()
            .Select(element => new ErrorVector(
                element.GetProperty("operation").GetString()!,
                element.GetProperty("name").GetString()!,
                element.GetProperty("status").GetInt32(),
                element.GetProperty("wire").GetString()!,
                element.GetProperty("code").GetString()!,
                element.GetProperty("message").GetString()!,
                element.GetProperty("parsed").GetRawText()))
            .ToList();
        return (requests, commands, responses, errors);
    }

    private static RequestVector[] ReadRequests(JsonElement vectors) =>
    [
        .. vectors.EnumerateArray().Select(element => new RequestVector(
            element.GetProperty("operation").GetString()!,
            element.GetProperty("name").GetString()!,
            element.GetProperty("target").GetString()!,
            element.GetProperty("body").GetString()!)),
    ];
}
